import pytest

from leetcode_py import logged_test

from .helpers import assert_calculate_time, run_calculate_time
from .solution import Solution


class TestSingleRowKeyboard:
    def setup_method(self):
        self.solution = Solution()

    @logged_test
    @pytest.mark.parametrize(
        "keyboard, word, expected",
        [
            ("abcdefghijklmnopqrstuvwxyz", "cba", 4),
            ("pqrstuvwxyzabcdefghijklmno", "leetcode", 73),
            ("abcdefghijklmnopqrstuvwxyz", "a", 0),
            ("abcdefghijklmnopqrstuvwxyz", "z", 25),
            ("abcdefghijklmnopqrstuvwxyz", "az", 25),
            ("abcdefghijklmnopqrstuvwxyz", "abc", 2),
            ("zyxwvutsrqponmlkjihgfedcba", "abc", 27),
            ("zyxwvutsrqponmlkjihgfedcba", "cba", 25),
            ("abcdefghijklmnopqrstuvwxyz", "hello", 20),
            ("qwertyuiopasdfghjklzxcvbnm", "type", 16),
            ("abcdefghijklmnopqrstuvwxyz", "keyboard", 117),
            ("abcdefghijklmnopqrstuvwxyz", "zzzzz", 25),
            ("mnbvcxzlkjhgfdsapoiuytrewq", "purchases", 70),
            (
                "bjxyfnqdmwglpocsutahkvzire",
                "zxssxbookwkwsagmahantzamcqcyurxcmpktaspznbzcuhugovmsbpdoeuuwnbfdotdixbugfbhtadmyotalnplzitpfhnrmhxwdhclmwicrephcjihrmrhn",
                979,
            ),
            (
                "abcdefghijklmnopqrstuvwxyz",
                "",
                25,
            ),
        ],
    )
    def test_calculate_time(self, keyboard: str, word: str, expected: int):
        result = run_calculate_time(Solution, keyboard, word)
        assert_calculate_time(result, expected)
